(* spec 0RB0LB_1LC1RD_1LA0RD_1RB1RC *)
Definition r_AST_146_0000 : list (option Trans) := [t0RB;t0LB;t1LC;t1RD;t1LA;t0RD;t1RB;t1RC].
Lemma cv_AST_146_0000 : coversTr (row_to_tm r_AST_146_0000).
Proof. assert(Hprogress:forall x,exists y,Reach1 source_AST_146_0000(family_AST_146_0000 x)(family_AST_146_0000 y)).
  { intros[T HT]. destruct(bca_zero_return source_AST_146_0000 eq_refl eq_refl eq_refl eq_refl
      eq_refl eq_refl eq_refl eq_refl T HT)as(U&HU&H).
    exists(exist bca_tail U HU);exact H. }
  assert(Hrec:forall N,exists j,N<=j /\ FiresAt(row_to_tm r_AST_146_0000)(StA,S0)j).
  { apply(conjugate_marked_return_fire source_AST_146_0000 _ perm_AST_146_0000 false
      _ family_AST_146_0000 (StA,S0) 34 boot_AST_146_0000).
    - intros[] [];reflexivity.
    - rewrite <-lift_c0. apply csteps_lift. vm_compute;reflexivity.
    - exact Hprogress.
    - intros[T HT];apply fires_here;reflexivity. }
  apply coversTr_nqh,neverqhtr_mirror.
  apply(ngram_check_neverqh_fuelmixtr_except_sound _ 3 0 2488 19
    skip_AST_146_0000 cert_AST_146_0000).
  - intros[[] []] H N;try discriminate.
    destruct(Hrec N)as(j&Hj&Hf). exists j;split;[exact Hj|apply mirror_fires;exact Hf].
  - vm_compute;reflexivity. Qed.

